import { NextRequest, NextResponse } from 'next/server'
import { Storage } from '@google-cloud/storage'

// Initialize Google Cloud Storage client using Application Default Credentials
const storage = new Storage({
  projectId: process.env.GOOGLE_CLOUD_PROJECT_ID || 'landbrugsdata',
  // Use Application Default Credentials (ADC) - works if gcloud is authenticated
})

const BUCKET_NAME = 'landbrugsdata-raw-data'
const PMTILES_BASE_PATH = 'gold/pmtiles'

interface PMTilesFile {
  year: number
  resolution: number
  timestamp: string
  size: number
  url: string
  lastModified: string
}

interface BNBOFile {
  filename: string
  size: number
  url: string
  lastModified: string
  type: 'bnbo_areas'
}

interface PMTilesMetadata {
  files: PMTilesFile[]
  years: number[]
  resolutions: number[]
  totalFiles: number
  lastUpdated: string
  bnbo?: {
    files: BNBOFile[]
    available: boolean
    status_codes: string[]
    status_colors: Record<string, string>
  }
}

export async function GET(request: NextRequest) {
  try {
    // Get all PMTiles files from GCS
    const [files] = await storage.bucket(BUCKET_NAME).getFiles({
      prefix: PMTILES_BASE_PATH,
      delimiter: '/',
    })
    
    // Filter and parse PMTiles files
    const pmtilesFiles: PMTilesFile[] = []
    
    for (const file of files) {
      if (!file.name.endsWith('.pmtiles')) continue
      
      // Parse H3 PFAS filename: gold/pmtiles/h3_pfas_2023_res10/20250705_181521/h3_pfas_2023_res10.pmtiles
      const h3Match = file.name.match(/h3_pfas_(\d{4})_res(\d+)\/(\d{8}_\d{6})\/h3_pfas_\d{4}_res\d+\.pmtiles$/)
      if (h3Match) {
        const [, yearStr, resolutionStr, timestamp] = h3Match
        const year = parseInt(yearStr)
        const resolution = parseInt(resolutionStr)
        
        // Get file metadata
        const [metadata] = await file.getMetadata()
        const size = parseInt(metadata.size?.toString() || '0')
        const lastModified = metadata.updated || new Date().toISOString()
        
        pmtilesFiles.push({
          year,
          resolution,
          timestamp,
          size,
          url: `/api/pmtiles/h3_pfas_${year}_res${resolution}.pmtiles`,
          lastModified,
        })
        continue
      }
    }
    
    // Sort by year and resolution
    pmtilesFiles.sort((a, b) => {
      if (a.year !== b.year) return a.year - b.year
      return a.resolution - b.resolution
    })
    
    // Extract unique years and resolutions
    const years = [...new Set(pmtilesFiles.map(f => f.year))].sort()
    const resolutions = [...new Set(pmtilesFiles.map(f => f.resolution))].sort()
    
    // Find latest timestamp for last updated
    const latestFile = pmtilesFiles.reduce((latest, current) => {
      return current.timestamp > latest.timestamp ? current : latest
    }, pmtilesFiles[0])
    
    const metadata: PMTilesMetadata = {
      files: pmtilesFiles,
      years,
      resolutions,
      totalFiles: pmtilesFiles.length,
      lastUpdated: latestFile?.lastModified || new Date().toISOString(),
    }
    
    return NextResponse.json(metadata, {
      headers: {
        'Cache-Control': 'public, max-age=300', // Cache for 5 minutes
        'Content-Type': 'application/json',
      },
    })
  } catch (error) {
    console.error('PMTiles metadata error:', error)
    
    return NextResponse.json(
      { 
        error: 'Failed to fetch PMTiles metadata',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    )
  }
} 